  updateNextWakeDisplay();
  updateTimeUntilNextWake();
  updateLastWakeDisplay();
  updateLastUpdateDisplay();
  updateCycleProgress();
  updateTotalWakesDisplay();
  updateDaysActiveDisplay();
}, 60000);
